import * as THREE from 'three';

export const DOMINO_HEIGHT = 1.5;

export function layDominoes(curvePoints, count, gap) {
  const height = DOMINO_HEIGHT;
  if (!(gap < 0.8 * height)) {
    throw new Error(`gap must be < ${0.8*height}`);
  }
  const pts = curvePoints.map(p => p.isVector3 ? p : new THREE.Vector3(...p));
  const curve = new THREE.CatmullRomCurve3(pts, false);
  curve.arcLengthDivisions = Math.max(1000, count * 500);
  const total = curve.getLength();

  const group = new THREE.Group();
  const width = 0.6;
  const thickness = 0.12;
  const geometry = new THREE.BoxGeometry(width, height, thickness);
  const material = new THREE.MeshStandardMaterial({ color: 0xffffff });

  const up = new THREE.Vector3(0,1,0);
  for (let i = 0; i < count; i++) {
    const s = Math.min(i*gap, total);
    const u = total === 0 ? 0 : s/total;
    const pos = curve.getPointAt(u);
    const tan = curve.getTangentAt(u).normalize();

    const pivot = new THREE.Group();
    pivot.position.copy(pos);
    // orient local +Z along tangent, keep Y up
    const zAxis = tan.clone().normalize();
    const xAxis = new THREE.Vector3().crossVectors(up, zAxis).normalize();
    const yAxis = new THREE.Vector3().crossVectors(zAxis, xAxis).normalize();
    pivot.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(xAxis,yAxis,zAxis));

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.y = height/2;
    pivot.add(mesh);

    pivot.userData = { index: i, basePosition: pos.clone(), thickness };
    pivot.name = `domino-${i}`;
    group.add(pivot);
  }
  return group;
}
```

