export const DOMINO_HEIGHT = 1.5;
const DOMINO_WIDTH = 0.6;
const DOMINO_THICKNESS = 0.12;

/**
 * Lay out `count` thin-box dominoes along an open CatmullRomCurve3 built
 * from `curvePoints`, at equal arc-length spacing of `gap`.
 *
 * Each domino sits in a pivot group whose origin is at its bottom-center
 * on the curve; the mesh inside is offset up by height/2 so the pivot can
 * tip it over about its base. The pivot is oriented so local +Z (the thin,
 * "facing" axis) points along the curve tangent, i.e. toward the next
 * domino.
 *
 * Returns a THREE.Group of pivot groups, each with userData:
 *   { index, basePosition, thickness }
 */
export function layDominoes(curvePoints, count, gap) {
  const height = DOMINO_HEIGHT;
  if (!(gap > 0)) {
    throw new Error(`gap must be positive, got ${gap}`);
  }
  // A real cascade needs the dominoes to overlap when fallen.
  if (!(gap < 0.8 * height)) {
    throw new Error(
      `gap must be < 0.8 * height (${(0.8 * height).toFixed(2)}) for a plausible cascade, got ${gap}`
    );
  }

  const points = curvePoints.map((p) =>
    p.isVector3 ? p.clone() : new THREE.Vector3(p[0], p[1], p[2])
  );
  const curve = new THREE.CatmullRomCurve3(points, false);
  // Refine arc-length table so equal-u sampling is arc-length-accurate.
  curve.arcLengthDivisions = Math.max(2000, count * 500);
  const total = curve.getLength();

  const group = new THREE.Group();
  group.name = 'domino-cascade';

  const geometry = new THREE.BoxGeometry(DOMINO_WIDTH, height, DOMINO_THICKNESS);
  const material = new THREE.MeshStandardMaterial({ color: 0xf5f5f5 });
  const up = new THREE.Vector3(0, 1, 0);

  for (let i = 0; i < count; i++) {
    const s = Math.min(i * gap, total);
    const u = total === 0 ? 0 : s / total;
    const pos = curve.getPointAt(u);
    const tangent = curve.getTangentAt(u).normalize();

    const pivot = new THREE.Group();
    pivot.name = `domino-${i}`;
    pivot.position.copy(pos);

    // Orient local +Z along the tangent (facing the next domino), Y up.
    const zAxis = tangent.clone();
    const xAxis = new THREE.Vector3().crossVectors(up, zAxis);
    if (xAxis.lengthSq() < 1e-12) {
      xAxis.set(1, 0, 0); // tangent is vertical; any perpendicular works
    } else {
      xAxis.normalize();
    }
    const yAxis = new THREE.Vector3().crossVectors(zAxis, xAxis).normalize();
    pivot.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(xAxis, yAxis, zAxis));

    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.y = height / 2; // bottom face rests on the pivot origin
    pivot.add(mesh);

    pivot.userData = { index: i, basePosition: pos.clone(), thickness: DOMINO_THICKNESS };
    group.add(pivot);
  }

  return group;
}

/**
 * Topple angle (radians) of domino `i` at time `t`.
 *
 * Domino i starts falling at i * startDelay and rotates about its
 * bottom-front edge through PI/2 over fallDur, with smoothstep easing.
 * Before its start time the angle is clamped to 0; after fallDur past
 * start it is fully at PI/2.
 */
export function toppleState(i, t, { startDelay = 0.15, fallDur = 0.4 } = {}) {
  const start = i * startDelay;
  if (t <= start) return 0;
  const f = Math.min(1, (t - start) / fallDur);
  return (Math.PI / 2) * f * f * (3 - 2 * f); // smoothstep(f)
}

/**
 * Apply toppleState to every pivot in the group returned by layDominoes.
 *
 * The rotation happens about the bottom-FRONT edge (local y=0, z=+d/2),
 * not the bottom center: while tipping by angle a, the pivot position is
 * compensated so that edge point stays fixed in world space.
 *
 * Positive rotation about local X tips +Y toward +Z, i.e. forward onto
 * the next domino.
 */
export function animateDominoes(group, t) {
  for (let i = 0; i < group.children.length; i++) {
    const pivot = group.children[i];
    const a = toppleState(i, t);

    pivot.rotation.x = a;

    const d = (pivot.userData && pivot.userData.thickness) || 0;
    const half = d / 2;
    const base =
      (pivot.userData && pivot.userData.basePosition) || pivot.position;
    // Keep the bottom-front edge pinned: pos = base + e - R_x(a) * e,
    // where e = (0, 0, d/2).
    pivot.position.set(
      base.x,
      base.y + half * Math.sin(a),
      base.z + half * (1 - Math.cos(a))
    );
  }
}
"})
