import * as THREE from 'three';
import {
  layDominoes,
  toppleState,
  animateDominoes,
  DOMINO_HEIGHT,
} from '../src/dominoes.js';

// Nearly straight path with a gentle bend (used for layout/orientation tests).
const CURVE_POINTS = [
  [0, 0, 0],
  [4, 0, 1],
  [8, 0, 0],
  [12, 0, -1],
];

// Collinear points: arc length and chord distance coincide exactly, so the
// spacing assertion can hold to 1e-6.
const STRAIGHT_POINTS = [
  [0, 0, 0],
  [3, 0, 0],
  [6, 0, 0],
];

function makeCascade(points = CURVE_POINTS, count = 8, gap = 0.9) {
  return layDominoes(points, count, gap);
}

describe('layDominoes', () => {
  it('rejects gaps too large for a plausible cascade', () => {
    expect(() => makeCascade(CURVE_POINTS, 8, DOMINO_HEIGHT * 0.8)).toThrow();
    expect(() => makeCascade(CURVE_POINTS, 8, 2)).toThrow();
    expect(() => makeCascade(CURVE_POINTS, 8, 1.1)).not.toThrow();
  });

  it('creates one pivot group per domino', () => {
    const group = makeCascade();
    expect(group.children.length).toBe(8);
    group.children.forEach((pivot) => {
      expect(pivot.type).toBe('Group');
      expect(pivot.children.length).toBe(1);
      const mesh = pivot.children[0];
      expect(mesh.geometry.parameters.height).toBe(DOMINO_HEIGHT);
      // thin box: thickness much smaller than height
      expect(mesh.geometry.parameters.depth).toBeLessThan(0.5);
    });
  });

  it('places neighbors at equal arc-length spacing gap within 1e-6', () => {
    const count = 10;
    const gap = 0.9;
    const group = makeCascade(STRAIGHT_POINTS, count, gap);
    for (let i = 0; i < count - 1; i++) {
      const a = group.children[i].position;
      const b = group.children[i + 1].position;
      const dist = a.distanceTo(b);
      expect(Math.abs(dist - gap)).toBeLessThanOrEqual(1e-6);
    }
  });

  it('orients each domino to face the next one along the tangent', () => {
    const group = makeCascade();
    const up = new THREE.Vector3(0, 1, 0);
    for (let i = 0; i < group.children.length - 1; i++) {
      const pivot = group.children[i];
      const facing = new THREE.Vector3(0, 0, 1)
        .applyQuaternion(pivot.quaternion)
        .normalize();
      const toNext = group.children[i + 1].position
        .clone()
        .sub(pivot.position)
        .normalize();
      expect(facing.dot(toNext)).toBeGreaterThan(0.99);
      // still upright: local Y close to world up on flat ground
      const localUp = new THREE.Vector3(0, 1, 0).applyQuaternion(pivot.quaternion);
      expect(localUp.dot(up)).toBeGreaterThan(0.99);
    }
  });
